const EN_FROM_DE=Object.fromEntries(Object.entries(DE).map(([en,de])=>[de,en]));
function translateCore(s,toDE){if(!s)return s;let map=toDE?DE:EN_FROM_DE;if(map[s])return map[s];let out=s;Object.keys(map).sort((a,b)=>b.length-a.length).forEach(k=>{if(out.includes(k))out=out.split(k).join(map[k]);});if(toDE){if(/^\d+ active DCS alarm/.test(s)){let n=parseInt(s,10);return `${n} aktive${n===1?'r':' '} DCS-Alarm${n===1?'':'e'}`;}out=out.replace(/\bNow\b/g,'Jetzt').replace(/\bHealthy\b/g,'Gesund').replace(/\bLow\b/g,'Niedrig').replace(/\bHIGH\b/g,'HOCH').replace(/\bMEDIUM\b/g,'MITTEL');}else{out=out.replace(/\bJetzt\b/g,'Now').replace(/\bGesund\b/g,'Healthy').replace(/\bNiedrig\b/g,'Low').replace(/\bHOCH\b/g,'HIGH').replace(/\bMITTEL\b/g,'MEDIUM');}return out;}
function applyLanguage(){let toDE=state.language==='DE';document.documentElement.lang=toDE?'de':'en';let walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){let p=node.parentElement;if(!p||['SCRIPT','STYLE','NOSCRIPT'].includes(p.tagName))continue;let raw=node.nodeValue,lead=raw.match(/^\s*/)?.[0]||'',trail=raw.match(/\s*$/)?.[0]||'',core=raw.trim();if(!core)continue;let trans=translateCore(core,toDE);if(trans!==core)node.nodeValue=lead+trans+trail;}let q=$('#tagSearch');if(q)q.placeholder=toDE?'Tag oder Parameter suchen…':'Search tag or parameter…';let lang=$('#languageSelect');if(lang)lang.value=state.language;document.title=toDE?'ProcessGuard AI | CDU-Intelligenz':'ProcessGuard AI | CDU Intelligence';updateRealClock();}
function updateRealClock(){let d=new Date(),de=state.language==='DE';let locale=de?'de-DE':'en-GB';$('#headerDate').textContent=new Intl.DateTimeFormat(locale,{day:'2-digit',month:'short',year:'numeric'}).format(d);$('#headerTime').textContent=new Intl.DateTimeFormat(locale,{hour:'2-digit',minute:'2-digit',hour12:false}).format(d);}

