function rnd(){state.seed=(Math.imul(state.seed,1664525)+1013904223)>>>0;return state.seed/4294967296;}
function randn(){return (rnd()+rnd()+rnd()+rnd()-2);}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function approach(a,b,r){return a+(b-a)*r;}
function ageMin(){return state.scenario?Math.max(0,(state.simSeconds-state.scenario.started)/60):0;}
function sf(){return state.severity==='strong'?1.45:state.severity==='mild'?.62:1;}
function residual(){return state.values.firing-state.values.expectedFiring;}
function dcsActive(){return state.alarms.filter(a=>a.active).length;}
function severityClass(l){return l==='ALERT'?'alert':l==='WATCH'||l==='ADVISORY'?'watch':'healthy';}
function fmtRuntime(){let s=Math.max(0,Math.floor(state.simSeconds));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function pct(v,b){return b?((v-b)/b*100):0;}
function fmtDelta(v,b,d=1){let p=pct(v,b);return `${p>=0?'+':''}${p.toFixed(d)}%`;}

function boundedNoise(key,base,amp,pull=.14){let v=state.values[key];return v+(base-v)*pull+randn()*amp;}

function scenarioTargets(){let v=state.values,z={...baseline,feedSP:v.feedSP,furnaceSP:v.furnaceSP,refluxSP:v.refluxSP};z.expectedFiring=55+(v.feedSP-1000)*.018+(250-v.preheat)*.18+(v.furnaceSP-382.5)*.42;if(!state.scenario)return z;let t=ageMin(),f=sf(),x=clamp(t/12,0,1),late=clamp((t-6)/14,0,1),down=clamp((t-9)/14,0,1);switch(state.scenario.type){case'furnace':Object.assign(z,{efficiency:89-8*f*x,firing:55+25*f*x,fuel:100+16*f*x,stack:345+22*f*x,coilDP:1.18+.20*f*x,tubeSkin:465+22*f*x,o2:3.10,furnace:v.furnaceSP-17*f*late,flash:345-13*f*down,dp:.42-.05*f*down,reflux:220+4*f*late,topP:1.35,naphtha:120-9*f*down,swing:60-4*f*down,kero:110-4*f*down,lgo:150+1*f*down,hgo:140+4*f*down,residue:160+12*f*down,offgas:30-3*f*down,energyPenalty:2.6*f*x,condDuty:22.8-1.7*f*down});break;case'valve':Object.assign(z,{valveCmd:80,valveFb:40,reflux:220-62*f*x,topP:1.35+.22*f*late,naphtha:120-5*f*down,residue:160+4*f*down,offgas:30+2*f*late});break;case'condenser':Object.assign(z,{condDuty:22.8-6.6*f*x,topP:1.35+.30*f*late,reflux:220-18*f*late,naphtha:120-4*f*down,residue:160+3*f*down,offgas:30+8*f*late});break;case'highFeed':Object.assign(z,{feed:v.feedSP+150*f*x,dp:.42+.22*f*late,topP:1.35+.15*f*late,reflux:220+7*f*late,naphtha:120+4*f*down,residue:160+7*f*down,offgas:30+5*f*down});break;case'preheat':Object.assign(z,{preheat:250-26*f*x,expectedFiring:55+7*f*x,firing:55+21*f*x,fuel:100+13*f*x,efficiency:89-3*f*x,energyPenalty:1.9*f*x,stack:345+10*f*x});break;}
return z;}

const noiseAmps={feed:.55,preheat:.10,furnace:.10,expectedFiring:.07,firing:.12,fuel:.08,stack:.22,o2:.008,coilDP:.002,tubeSkin:.22,efficiency:.03,flash:.10,topP:.0018,dp:.0013,reflux:.25,offgas:.06,valveCmd:.08,valveFb:.08,condDuty:.025,naphtha:.08,swing:.05,kero:.05,lgo:.05,hgo:.05,residue:.08,energyPenalty:.01};
function updateProcess(){let v=state.values,t=scenarioTargets();Object.keys(t).forEach(k=>{if(typeof t[k]!=='number'||k.endsWith('SP')||k==='dataConfidence')return;let target=t[k],amp=noiseAmps[k]??.04,pull=['furnace','flash','topP','dp','reflux','feed'].includes(k)?.12:.09;v[k]=approach(v[k],target,pull)+randn()*amp;});let f=residual();if(v.furnace<364)raiseAlarm('101-TIC-201','Furnace outlet temperature LOW','HIGH');if(v.reflux<175)raiseAlarm('101-FIC-401','Reflux flow LOW','HIGH');if(v.topP>1.55)raiseAlarm('101-PIC-301','Column top pressure HIGH','MEDIUM');if(v.dp>.58)raiseAlarm('101-PDI-008','Column ΔP HIGH','MEDIUM');if(state.scenario?.type==='furnace'&&f>8&&!state.events.some(e=>e.code==='PG_FIRING'))state.events.push({code:'PG_FIRING',t:state.simSeconds,label:'ProcessGuard early deviation',text:'Abnormal heater firing demand for current load and preheat conditions.'});}

function raiseAlarm(tag,msg,priority){let a=state.alarms.find(x=>x.tag===tag&&x.msg===msg);if(a){a.active=true;return;}state.alarms.push({tag,msg,priority,active:true,ack:false,t:state.simSeconds});}

function score(){if(!state.scenario)return 0;let v=state.values,t=ageMin(),s=0;switch(state.scenario.type){case'furnace':s+=clamp(Math.max(0,residual()-4)*2.8,0,35)+clamp(t*1.2,0,20)+clamp((89-v.efficiency)*2.1,0,15)+clamp((v.coilDP-1.18)*48+(v.tubeSkin-465)*.27,0,15)+clamp((v.stack-345)*.2,0,5)+clamp(Math.max(0,345-v.flash)*1.3,0,10);break;case'valve':s=clamp(Math.abs(v.valveCmd-v.valveFb)*1.8+(220-v.reflux)*.65+t*.7,0,100);break;case'condenser':s=clamp((22.8-v.condDuty)*8+(v.topP-1.35)*110+t*.6,0,100);break;case'highFeed':s=clamp((v.feed-1000)*.24+(v.dp-.42)*120+t*.45,0,100);break;case'preheat':s=clamp((250-v.preheat)*1.6+Math.max(0,residual()-3)*2+t*.45,0,100);break;}return Math.round(clamp(s,0,100));}
function level(){let s=score();return s>=66?'ALERT':s>=41?'WATCH':s>=21?'ADVISORY':'NORMAL';}
function unitHealth(){return clamp(94-Math.round(score()*.28),58,96);}
function alarmForecast(){if(!state.scenario)return'—';let v=state.values;switch(state.scenario.type){case'furnace':return v.furnace<=364?'Now':'~8–11 min';case'valve':return v.reflux<175?'Now':'~6–12 min';case'condenser':return v.topP>1.55?'Now':'~7–14 min';case'highFeed':return v.dp>.58?'Now':'~10–18 min';default:return'~12–20 min';}}

function snapshot(tMin){let v=state.values,o={tMin};Object.entries(trendDefs).forEach(([k,d])=>{o[k]=d.calc?d.calc(v):v[d.field];if(d.sp)o[k+'SP']=v[d.sp];if(d.model)o[k+'Model']=v[d.model];});return o;}
function seedHistory(){state.history=[];let temp={...baseline};let save={...state.values};for(let i=0;i<=2880;i++){let tMin=-1440+i*.5;temp.feed+=(1000-temp.feed)*.11+randn()*.45;temp.furnace+=(382.5-temp.furnace)*.1+randn()*.09;temp.topP+=(1.35-temp.topP)*.12+randn()*.0015;temp.dp+=(.42-temp.dp)*.12+randn()*.0012;temp.reflux+=(220-temp.reflux)*.1+randn()*.22;temp.offgas+=(30-temp.offgas)*.1+randn()*.05;temp.firing+=(55-temp.firing)*.1+randn()*.10;temp.expectedFiring+=(55-temp.expectedFiring)*.1+randn()*.05;temp.preheat+=(250-temp.preheat)*.1+randn()*.08;temp.stack+=(345-temp.stack)*.1+randn()*.18;temp.o2+=(3.1-temp.o2)*.1+randn()*.006;temp.coilDP+=(1.18-temp.coilDP)*.1+randn()*.0015;temp.tubeSkin+=(465-temp.tubeSkin)*.1+randn()*.18;temp.efficiency+=(89-temp.efficiency)*.1+randn()*.025;temp.flash+=(345-temp.flash)*.1+randn()*.08;temp.naphtha+=(120-temp.naphtha)*.1+randn()*.06;temp.residue+=(160-temp.residue)*.1+randn()*.06;temp.condDuty+=(22.8-temp.condDuty)*.1+randn()*.018;temp.valveFb+=(55-temp.valveFb)*.1+randn()*.06;state.values={...save,...temp};state.history.push(snapshot(tMin));}state.values={...save};}

function tick(){if(!state.running||state.paused)return;state.simSeconds+=30*state.speed;updateProcess();state.history.push(snapshot(state.simSeconds/60));if(state.history.length>2881)state.history.shift();render();}

function rangeRows(hours){let count=Math.min(state.history.length,Math.round(hours*120)+1);return state.history.slice(-count);}
function formatValue(v,d){if(v==null||Number.isNaN(v))return'—';let n=Math.abs(v)>=100?v.toFixed(0):Math.abs(v)>=10?v.toFixed(1):v.toFixed(2);return`${n} ${d.unit}`;}
function chartSvg(key,hours=1,compact=false){let d=trendDefs[key],rows=rangeRows(hours),W=compact?320:520,H=compact?132:180,L=compact?35:42,R=8,T=8,B=24,vals=rows.map(r=>r[key]).filter(Number.isFinite);if(d.sp)vals.push(...rows.map(r=>r[key+'SP']).filter(Number.isFinite));vals.push(...d.typical);let min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;min-=span*.18;max+=span*.18;let x=i=>L+(W-L-R)*i/Math.max(1,rows.length-1),y=v=>T+(H-T-B)*(1-(v-min)/(max-min)),path=k=>rows.map((r,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(r[k]).toFixed(1)}`).join(' '),ticks=[0,.25,.5,.75,1],typTop=y(d.typical[1]),typBot=y(d.typical[0]),eventIndex=state.scenario?rows.findIndex(r=>r.tMin>=state.scenario.started/60):-1,cur=rows.at(-1)?.[key];return`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${d.name} trend"><rect class="chart-typical" x="${L}" y="${typTop}" width="${W-L-R}" height="${Math.max(2,typBot-typTop)}"/>${ticks.map(q=>{let yy=T+(H-T-B)*q;return`<line class="chart-grid-line" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="chart-axis" x="${L-4}" y="${yy+3}" text-anchor="end">${(max-(max-min)*q).toFixed(Math.abs(max)<10?2:0)}</text>`}).join('')}${eventIndex>=0?`<line class="chart-event" x1="${x(eventIndex)}" x2="${x(eventIndex)}" y1="${T}" y2="${H-B}"/>`:''}<path class="chart-current" d="${path(key)}"/>${d.sp?`<path class="chart-typical" style="fill:none" d="${path(key+'SP')}"/>`:''}${[0,.166,.333,.5,.666,.833,1].map(q=>{let idx=Math.round((rows.length-1)*q),m=rows[idx]?.tMin??0,label=m<0?`T${Math.round(m)}m`:`${String(Math.floor(m/60)).padStart(2,'0')}:${String(Math.floor(m)%60).padStart(2,'0')}`;return`<text class="chart-axis" x="${x(idx)}" y="${H-5}" text-anchor="middle">${label}</text>`}).join('')}</svg>`;}

function renderHeader(){let l=level(),cls=severityClass(l),h=unitHealth();updateRealClock();$('#simTime').textContent=fmtRuntime();$('#simStateText').textContent=state.running?(state.paused?'SIMULATOR PAUSED':'SYNTHETIC LIVE PLANT'):'SIMULATOR HELD';$('#simDot').className=state.running&&!state.paused?'live':'';$('#startBtn').disabled=state.running&&!state.paused;$('#pauseBtn').disabled=!state.running;$('#pauseBtn').textContent=state.paused?'▶ Resume':'Ⅱ Pause';$('#injectBtn').disabled=!state.running;let box=$('#unitStatusBox');box.className=`unit-status ${cls}`;$('#unitStatusTitle').textContent=l==='NORMAL'?'Unit Operating Normally':`${l} — ${scenarioCfg[state.scenario.type].name}`;$('#unitStatusText').textContent=l==='NORMAL'?'No critical issues. AI monitoring active.':`ProcessGuard deviation score ${score()}/100 · DCS alarms ${dcsActive()}`;$('#healthGauge').style.setProperty('--health',h);$('#healthValue').textContent=`${h}%`;$('#healthLabel').textContent=l==='NORMAL'?'Stable':l==='ADVISORY'?'Monitor':l==='WATCH'?'Watch':'Degraded';}

function renderPfd(){let v=state.values;$('#pfdFeedFlow').textContent=`${v.feed.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g,',')} m³/h`;$('#pfdFeedTemp').textContent=`${v.feedTemp.toFixed(0)} °C`;$('#pfdPreheatTemp').textContent=`Outlet: ${v.preheat.toFixed(0)} °C`;$('#pfdFurnaceTemp').textContent=`${v.furnace.toFixed(1)} °C`;$('#pfdTopP').textContent=`${v.topP.toFixed(2)} bar(g)`;$('#pfdOvhdProductFlow').textContent=`${v.offgas.toFixed(1)} m³/h`;$('#pfdReflux').textContent=`${v.reflux.toFixed(0)} m³/h`;$('#pfdNaphthaFlow').textContent=`${v.naphtha.toFixed(0)} m³/h`;$('#pfdSwingFlow').textContent=`${v.swing.toFixed(0)} m³/h`;$('#pfdKeroFlow').textContent=`${v.kero.toFixed(0)} m³/h`;$('#pfdLgoFlow').textContent=`${v.lgo.toFixed(0)} m³/h`;$('#pfdHgoFlow').textContent=`${v.hgo.toFixed(0)} m³/h`;$('#pfdResidueFlow').textContent=`${v.residue.toFixed(0)} m³/h`;let svg=$('#cduPfd');$$('.active-equip',svg).forEach(e=>e.classList.remove('active-equip'));if(state.scenario){let target={furnace:'furnace',valve:'reflux',condenser:'condenser',highFeed:'column',preheat:'preheat'}[state.scenario.type];let el=svg.querySelector(`[data-equip="${target}"]`);if(el)el.classList.add('active-equip');}renderDisplayMode();}

function renderDisplayMode(){let svg=$('#cduPfd'),chip=$('#displayStatusChip');svg.classList.remove('mode-values','mode-equipment','mode-ai','ai-normal');svg.classList.add(`mode-${state.displayMode}`);if(state.displayMode==='values'){chip.className='display-status-chip';chip.textContent='Live values';return;}if(state.displayMode==='equipment'){chip.className='display-status-chip equipment';chip.textContent='Equipment focus';return;}let l=level();if(!state.scenario)svg.classList.add('ai-normal');chip.className=`display-status-chip ${severityClass(l)}`;chip.textContent=state.scenario?`AI overlay · ${l}`:'AI overlay · Normal';}

function renderAlarmAi(){let l=level(),cls=severityClass(l),active=dcsActive(),unack=state.alarms.filter(a=>a.active&&!a.ack).length;$('#alarmNavBadge').textContent=active;$('#incidentNavBadge').textContent=state.scenario?1:0;$('#alarmActiveCount').textContent=active;$('#alarmUnackCount').textContent=unack;let a=$('#alarmSummary');a.className=`alarm-summary ${active?active>1?'alert':'watch':'healthy'}`;a.querySelector('.circle-icon').textContent=active?'!':'✓';a.querySelector('strong').textContent=active?`${active} active DCS alarm${active>1?'s':''}`:'No active critical alarms';let ai=$('#aiStateBox');ai.className=`ai-state ${cls}`;ai.querySelector('.circle-icon').textContent=l==='NORMAL'?'✓':'!';$('#aiStateTitle').textContent=l==='NORMAL'?'Normal Operation':`${l} — ${scenarioCfg[state.scenario.type].name}`;$('#aiStateText').textContent=l==='NORMAL'?'No abnormal patterns detected.':state.scenario.type==='furnace'?`Firing residual ${residual().toFixed(1)} %-pt · predicted DCS alarm ${alarmForecast()}`:`Correlated evidence detected · predicted DCS alarm ${alarmForecast()}`;}

function setBar(id,p){$(id).style.width=`${clamp(50+p*3,8,96)}%`;}
function renderKpis(){let v=state.values;$('#kpiFeed').textContent=`${v.feed.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g,',')} m³/h`;$('#kpiFeedDelta').textContent=fmtDelta(v.feed,baseline.feed);$('#kpiFurnace').textContent=`${v.furnace.toFixed(1)} °C`;$('#kpiFurnaceDelta').textContent=fmtDelta(v.furnace,baseline.furnace);$('#kpiTopP').textContent=`${v.topP.toFixed(2)} bar(g)`;$('#kpiTopPDelta').textContent=fmtDelta(v.topP,baseline.topP);$('#kpiReflux').textContent=`${v.reflux.toFixed(0)} m³/h`;$('#kpiRefluxDelta').textContent=fmtDelta(v.reflux,baseline.reflux);$('#kpiDP').textContent=`${v.dp.toFixed(2)} bar`;$('#kpiDPDelta').textContent=fmtDelta(v.dp,baseline.dp);$('#kpiResidue').textContent=`${v.residue.toFixed(0)} m³/h`;$('#kpiResidueDelta').textContent=fmtDelta(v.residue,baseline.residue);setBar('#barFeed',pct(v.feed,baseline.feed));setBar('#barFurnace',pct(v.furnace,baseline.furnace));setBar('#barTopP',pct(v.topP,baseline.topP));setBar('#barReflux',pct(v.reflux,baseline.reflux));setBar('#barDP',pct(v.dp,baseline.dp));setBar('#barResidue',pct(v.residue,baseline.residue));$('#ctxMode').textContent=state.scenario?scenarioCfg[state.scenario.type].name:'Normal';$('#ctxFeed').textContent=`${v.feed.toFixed(0)} m³/h`;$('#ctxDuty').textContent=`${(baseline.furnaceDuty+v.energyPenalty*4.5).toFixed(0)} MW`;$('#ctxEvent').textContent=state.scenario?scenarioCfg[state.scenario.type].title:'–';}

function renderSelectedTrend(){$('#selectedTrendChart').innerHTML=chartSvg(state.selectedTrend,state.trendHours,false);}
function trendTile(key){let d=trendDefs[key],cur=state.history.at(-1)?.[key];return`<article class="trend-tile"><header><div><h3>${d.name}</h3><small>${d.unit} · typical ${d.typical[0]}–${d.typical[1]}</small></div><strong>${formatValue(cur,d)}</strong></header>${chartSvg(key,Math.min(4,state.trendHours),true)}</article>`;}
function renderAllTrends(){let keys=['furnace','firing','residual','stack','o2','coilDP','tubeSkin','efficiency','flash','topP','offgas','dp','reflux','feed','preheat','naphtha','residue','condDuty','valveFb'];$('#allTrendsGrid').innerHTML=keys.map(trendTile).join('');}

function evidence(type){let v=state.values;if(type==='furnace')return[['Firing residual',`${residual().toFixed(1)} %-pt`,'Actual firing above model expectation'],['Stack temperature',`${v.stack.toFixed(1)} °C`,'Energy loss increasing'],['Coil ΔP',`${v.coilDP.toFixed(2)} bar`,'Supports developing fouling/coking'],['Tube-skin temperature',`${v.tubeSkin.toFixed(0)} °C`,'Heat-transfer resistance'],['Flue-gas O₂',`${v.o2.toFixed(2)} %`,'Combustion broadly normal'],['Feed / preheat',`${v.feed.toFixed(0)} m³/h / ${v.preheat.toFixed(0)} °C`,'Load context']];if(type==='valve')return[['Valve command',`${v.valveCmd.toFixed(0)}%`,'Controller demand'],['Valve feedback',`${v.valveFb.toFixed(0)}%`,'Position mismatch'],['Reflux flow',`${v.reflux.toFixed(0)} m³/h`,'Process consequence'],['Top pressure',`${v.topP.toFixed(2)} bar(g)`,'Overhead response']];if(type==='condenser')return[['Condenser duty',`${v.condDuty.toFixed(1)} MW`,'Heat removal reduced'],['Top pressure',`${v.topP.toFixed(2)} bar(g)`,'Pressure response'],['Reflux',`${v.reflux.toFixed(0)} m³/h`,'Overhead balance changing']];if(type==='highFeed')return[['Crude feed',`${v.feed.toFixed(0)} m³/h`,'Throughput increase'],['Column ΔP',`${v.dp.toFixed(2)} bar`,'Hydraulic loading'],['Top pressure',`${v.topP.toFixed(2)} bar(g)`,'Pressure response']];return[['Preheat outlet',`${v.preheat.toFixed(0)} °C`,'Heat recovery degrading'],['Firing residual',`${residual().toFixed(1)} %-pt`,'Furnace compensating'],['Energy penalty',`${v.energyPenalty.toFixed(1)} MW`,'Efficiency impact']];}
function ranks(type){if(type==='furnace')return[['Coil fouling / heat-transfer degradation',72],['Combustion-side degradation',16],['Feed-property change',7],['Instrumentation issue',5]];if(type==='valve')return[['Valve stiction / positioner issue',74],['Actuator issue',16],['Flow measurement issue',10]];if(type==='condenser')return[['Cooling-side performance loss',66],['Condenser fouling',24],['Pressure measurement issue',10]];if(type==='highFeed')return[['Hydraulic loading / flooding approach',78],['Feed-property shift',12],['ΔP measurement issue',10]];return[['Exchanger fouling',70],['Hot-side availability reduction',20],['Temperature measurement issue',10]];}
function eventMap(type){let nodes=type==='furnace'?['Heat transfer ↓','Firing demand ↑','Stack T ↑','Efficiency ↓','Furnace outlet T ↓','Flash vaporization ↓','Column ΔP ↓','Light products ↓ / residue ↑']:type==='valve'?['Valve response mismatch','Reflux flow ↓','Top pressure/T shift','Separation risk']:type==='condenser'?['Heat removal ↓','Top pressure ↑','Condensation changes','Overhead stability risk']:type==='highFeed'?['Feed ↑','Vapor/liquid traffic ↑','Column ΔP ↑','Flooding risk']:['Preheat recovery ↓','Furnace load ↑','Energy penalty ↑','Throughput margin ↓'];let active=Math.min(nodes.length-1,Math.floor(ageMin()/3));return`<div class="event-map">${nodes.map((n,i)=>`${i?'<span class="event-arrow">→</span>':''}<div class="event-node ${i<=active?'active':''}">${n}</div>`).join('')}</div>`;}
function workspaceHtml(){if(!state.scenario)return'<div class="workspace-card wide"><h3>No active incident</h3><p>Start the simulator and inject a scenario to activate the ProcessGuard investigation workflow.</p></div>';let type=state.scenario.type,v=state.values,e=evidence(type);if(state.workspaceTab==='summary')return`<div class="workspace-grid"><div class="workspace-card"><h3>Deviation Score</h3><div class="score-layout"><div class="score-ring" style="--score:${score()}"><div><strong>${score()}</strong><small>/100</small></div></div><div><b>${level()}</b><p>${type==='furnace'?'Heater firing demand is deviating from model expectation before conventional low-temperature alarm.':'Correlated evidence is developing across the process.'}</p></div></div></div><div class="workspace-card"><h3>ProcessGuard vs DCS</h3><p><b>DCS alarms:</b> ${dcsActive()}<br><b>ProcessGuard state:</b> ${level()}<br><b>Predicted alarm window:</b> ${alarmForecast()}</p></div><div class="workspace-card wide"><h3>Cause → effect map</h3>${eventMap(type)}</div><div class="workspace-card"><h3>Production / energy impact</h3><ul><li>Energy penalty ${v.energyPenalty.toFixed(1)} MW</li><li>Naphtha ${(v.naphtha-baseline.naphtha).toFixed(1)} m³/h vs normal</li><li>Residue ${(v.residue-baseline.residue).toFixed(1)} m³/h vs normal</li></ul></div><div class="workspace-card"><h3>Data provenance</h3><p>Plant-style PVs: M · GOOD<br>Residual/efficiency: CALCULATED<br>Expected firing/forecast: MODEL</p></div></div>`;if(state.workspaceTab==='evidence')return`<div class="workspace-card wide"><h3>Evidence Matrix</h3><table class="data-table"><tr><th>Evidence</th><th>Current</th><th>Interpretation</th></tr>${e.map(r=>`<tr><td>${r[0]}</td><td><b>${r[1]}</b></td><td>${r[2]}</td></tr>`).join('')}</table></div>`;if(state.workspaceTab==='root')return`<div class="workspace-grid"><div class="workspace-card"><h3>Diagnostic ranking</h3><div class="rank-list">${ranks(type).map(r=>`<div class="rank-row"><span>${r[0]}</span><span class="bar"><i style="width:${r[1]}%"></i></span><b>${r[1]}%</b></div>`).join('')}</div><p>Diagnostic ranking — not confirmed root cause.</p></div><div class="workspace-card"><h3>Leading evidence</h3><ul>${e.slice(0,5).map(r=>`<li><b>${r[0]}:</b> ${r[2]}</li>`).join('')}</ul></div></div>`;if(state.workspaceTab==='forecast')return`<div class="workspace-card wide"><h3>+5 / +10 / +20 min forecast</h3><table class="data-table"><tr><th>Horizon</th><th>Furnace outlet</th><th>Flash-zone</th><th>Column ΔP</th><th>Naphtha</th><th>Residue</th></tr>${[0,5,10,20].map(m=>`<tr><td>+${m} min</td><td>${(v.furnace-m*.35).toFixed(1)} °C</td><td>${(v.flash-m*.26).toFixed(1)} °C</td><td>${(v.dp-(type==='furnace'?m*.0012:0)).toFixed(2)} bar</td><td>${(v.naphtha-m*.30).toFixed(0)} m³/h</td><td>${(v.residue+m*.35).toFixed(0)} m³/h</td></tr>`).join('')}</table><p><b>Predicted DCS alarm:</b> ${alarmForecast()} · confidence Medium–High</p></div>`;if(state.workspaceTab==='whatif')return`<div class="workspace-card wide"><h3>What-if Twin</h3><p>Approved test variables: crude feed SP, furnace outlet SP, reflux SP and limited side-draw adjustment. What-if results are simulation-only and never written to the plant.</p><button class="action primary" onclick="showView('engineer')">Open Engineer View →</button></div>`;if(state.workspaceTab==='replay')return`<div class="workspace-card wide"><h3>Engineering Event Reconstruction</h3>${eventMap(type)}<p>Replay stores the incident as one correlated event rather than flooding the user with separate alarms for every related tag.</p></div>`;return`<div class="workspace-grid"><div class="workspace-card"><h3>Layered hybrid model</h3><ul><li>Physics/process model → expected behavior</li><li>Residual/anomaly model → unusual behavior</li><li>Diagnostic logic → likely causes</li><li>Forecast → what happens next</li><li>What-if twin → test options</li><li>AI → explain evidence</li></ul></div><div class="workspace-card"><h3>Current model calculation</h3><p><b>Firing residual = actual ${v.firing.toFixed(1)}% − expected ${v.expectedFiring.toFixed(1)}% = ${residual().toFixed(1)} %-pt</b></p><p>Estimated heater efficiency = useful heat absorbed / fuel energy input.</p></div></div>`;}

function renderSecondary(){let l=level(),v=state.values,e=state.scenario?evidence(state.scenario.type):[];$('#workspaceContent').innerHTML=workspaceHtml();$('#operatorIncidentPanel').innerHTML=state.scenario?`<section><h3>${scenarioCfg[state.scenario.type].name}</h3><p>ProcessGuard: <b>${l}</b> · score ${score()}/100 · DCS alarms ${dcsActive()}</p><p>Predicted DCS alarm: ${alarmForecast()}</p></section><section><h3>Recommended checks</h3><ul>${operatorChecks().map(x=>`<li>${x}</li>`).join('')}</ul></section><section><h3>Process impact</h3><p>Furnace ${v.furnace.toFixed(1)} °C · Top P ${v.topP.toFixed(2)} bar(g) · ΔP ${v.dp.toFixed(2)} bar</p></section>`:'<section><h3>No active incident</h3><p>Unit is operating within the synthetic normal envelope.</p></section>';$('#engineerPanel').innerHTML=state.scenario?`<section><h3>Model residual</h3><p>Firing residual <b>${residual().toFixed(1)} %-pt</b><br>Deviation score <b>${score()}/100</b></p></section><section><h3>Root-cause ranking</h3>${ranks(state.scenario.type).slice(0,3).map(r=>`<p>${r[0]} — <b>${r[1]}%</b></p>`).join('')}</section><section><h3>Forecast</h3><p>Predicted DCS alarm ${alarmForecast()}<br>Data confidence ${v.dataConfidence.toFixed(0)}%</p></section>`:'<section><h3>No active incident</h3><p>Inject a scenario to inspect model evidence.</p></section>';renderTags();renderAlarmCompare();renderMassBalance();renderReports();renderScenarioExplain();}

function operatorChecks(){if(!state.scenario)return['✓ No immediate action required.','✓ Continue normal monitoring.','✓ Review trends if any parameter deviates.','✓ Use Scenario Testing to explore abnormal conditions.'];let t=state.scenario.type;if(t==='furnace')return['Review F-101 TIC PV / SP / OP and firing demand.','Compare stack temperature, coil ΔP and tube-skin temperature.','Check current preheat outlet and feed conditions.','Use the What-if Twin before considering any operating change.'];if(t==='valve')return['Compare reflux controller OP with valve position feedback.','Check reflux flow and drum level trend.','Review valve/positioner local indication.'];if(t==='condenser')return['Review cooling-side conditions and condenser duty.','Monitor top pressure and reflux behavior.','Compare current duty against model expectation.'];if(t==='highFeed')return['Review column ΔP and hydraulic margin.','Monitor top pressure and tray-temperature response.','Confirm feed target and throughput context.'];return['Review preheat outlet temperature across the exchanger train.','Compare furnace demand against model expectation.','Review exchanger heat-recovery performance.'];}
function renderOperatorChecks(){$('#operatorChecks').innerHTML=operatorChecks().map(x=>`<li>${x.startsWith('✓')?x:'✓ '+x}</li>`).join('');}

function renderTags(){let v=state.values,rows=[['101-FIC-101','Crude feed',v.feed,'m³/h','M','GOOD'],['101-TIC-201','Furnace outlet',v.furnace,'°C','M','GOOD'],['PG-MDL-FIRE','Expected firing demand',v.expectedFiring,'%','MODEL','SYNC'],['PG-CAL-RES','Firing residual',residual(),'%-pt','C','GOOD'],['101-TI-STACK','Stack temperature',v.stack,'°C','M','GOOD'],['101-AI-O2','Flue-gas O₂',v.o2,'%','M','GOOD'],['101-PDI-COIL','Coil ΔP',v.coilDP,'bar','M','GOOD'],['101-TI-SKIN','Tube-skin temperature',v.tubeSkin,'°C','M','GOOD'],['PG-CAL-EFF','Estimated heater efficiency',v.efficiency,'%','C','GOOD'],['101-PIC-301','Column top pressure',v.topP,'bar(g)','M','GOOD'],['PG-SIM-OVHD','Overhead product / off-gas flow',v.offgas,'m³/h','SIM','GOOD'],['101-PDI-008','Column ΔP',v.dp,'bar','M','GOOD'],['101-FIC-401','Reflux flow',v.reflux,'m³/h','M','GOOD']];$('#tagTableWrap').innerHTML=`<table class="data-table"><tr><th>Tag</th><th>Parameter</th><th>Value</th><th>Unit</th><th>Source</th><th>Quality</th></tr>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${typeof r[2]==='number'?r[2].toFixed(Math.abs(r[2])<10?2:1):r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${r[5]}</td></tr>`).join('')}</table>`;}
function renderAlarmCompare(){$('#alarmComparePanel').innerHTML=`<div class="workspace-grid"><div class="workspace-card"><h3>DCS / controls</h3><p>Active alarms: <b>${dcsActive()}</b></p>${state.alarms.length?`<table class="data-table"><tr><th>Tag</th><th>Alarm</th><th>Status</th></tr>${state.alarms.map(a=>`<tr><td>${a.tag}</td><td>${a.msg}</td><td>${a.active?'ACTIVE':'CLEARED'}</td></tr>`).join('')}</table>`:'<p>No configured DCS limit is active.</p>'}</div><div class="workspace-card"><h3>ProcessGuard predictive layer</h3><p>Incident: <b>${state.scenario?level():'NORMAL'}</b><br>Deviation score: <b>${score()}/100</b><br>Predicted DCS alarm: <b>${alarmForecast()}</b></p></div></div>`;}
function renderMassBalance(){let v=state.values,total=v.naphtha+v.swing+v.kero+v.lgo+v.hgo+v.residue+v.offgas;let products=[['Off-gas/LPG',v.offgas],['Naphtha',v.naphtha],['Swing Naphtha',v.swing],['Kerosene',v.kero],['LGO',v.lgo],['HGO',v.hgo],['Atmospheric Residue',v.residue]];$('#massBalancePanel').innerHTML=`<div class="workspace-grid"><div class="workspace-card"><h3>Product distribution</h3><table class="data-table"><tr><th>Product</th><th>Flow</th><th>Share of shown products</th></tr>${products.map(p=>`<tr><td>${p[0]}</td><td>${p[1].toFixed(0)} m³/h</td><td>${(p[1]/total*100).toFixed(1)}%</td></tr>`).join('')}</table></div><div class="workspace-card"><h3>Operating impact</h3><p>Energy penalty: <b>${v.energyPenalty.toFixed(1)} MW</b><br>Naphtha change: <b>${(v.naphtha-baseline.naphtha).toFixed(1)} m³/h</b><br>Residue change: <b>${(v.residue-baseline.residue).toFixed(1)} m³/h</b></p><p>Displayed product flows are synthetic demonstration values.</p></div></div>`;}
function renderReports(){$('#reportsPanel').innerHTML=`<div class="settings-grid"><section><h3>Model Health</h3><p>Physics model: Healthy<br>Anomaly model: Healthy<br>Forecast model: Healthy<br>Data drift: Low</p></section><section><h3>Incident Summary</h3><p>${state.scenario?`${scenarioCfg[state.scenario.type].name}<br>Score ${score()}/100 · ${level()}<br>DCS alarms ${dcsActive()}`:'No active incident'}</p></section><section><h3>Future Connection</h3><p>DCS / historian / OPC UA → ProcessGuard data layer, with UniSim/HYSYS-derived process model running in parallel.</p></section></div>`;}
function renderScenarioExplain(){$('#scenarioExplanation').innerHTML=state.scenario?`<h3>${scenarioCfg[state.scenario.type].name}</h3><p>${scenarioCfg[state.scenario.type].title}</p><p><b>ProcessGuard:</b> ${level()} · score ${score()}/100<br><b>DCS alarms:</b> ${dcsActive()}<br><b>Predicted alarm:</b> ${alarmForecast()}</p>${eventMap(state.scenario.type)}`:'<h3>Scenario workflow</h3><p>Select a disturbance, start the synthetic plant, and inject the case. The same workflow is used for all cases: Detect → Correlate → Explain → Forecast → What-if → Replay.</p>';}

function render(){renderHeader();renderPfd();renderAlarmAi();renderKpis();renderSelectedTrend();renderAllTrends();renderOperatorChecks();renderSecondary();applyLanguage();}

function showView(name){state.selectedView=name;$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('[data-view-link]').forEach(b=>b.classList.toggle('active',b.dataset.viewLink===name));if(['overview','operator','engineer'].includes(name)&&$('#roleSelect')){$('#roleSelect').value=name;state.role=name;}if(name==='trends')renderAllTrends();window.scrollTo({top:0,behavior:'smooth'});}window.showView=showView;
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2300);}
function start(){state.running=true;state.paused=false;toast(state.language==='DE'?'Synthetische CDU aus dem Stationärbetrieb gestartet':'Synthetic CDU started from steady state');render();}
function pause(){state.paused=!state.paused;toast(state.language==='DE'?(state.paused?'Simulation pausiert':'Simulation fortgesetzt'):(state.paused?'Simulation paused':'Simulation resumed'));render();}
function steady(){state.scenario=null;state.severity='medium';state.alarms=[];state.events=[];state.values={...baseline,feedSP:state.values.feedSP,furnaceSP:state.values.furnaceSP,refluxSP:state.values.refluxSP};toast(state.language==='DE'?'Zum Stationärbetrieb zurückgekehrt':'Returned to steady state');render();}
function stopReset(){state.running=false;state.paused=false;state.simSeconds=0;state.scenario=null;state.severity='medium';state.alarms=[];state.events=[];state.values={...baseline};state.seed=314159265;seedHistory();toast(state.language==='DE'?'Simulation gestoppt und auf 00:00:00 zurückgesetzt':'Simulation stopped and reset to 00:00:00');render();}
function inject(type,severity){if(!state.running){toast(state.language==='DE'?'Bitte zuerst die Live-Anlage starten':'Start the live plant first');return;}state.scenario={type,started:state.simSeconds};state.severity=severity;state.events.push({code:'INJECT',t:state.simSeconds,label:'Scenario injected',text:scenarioCfg[type].title});toast(`${translateCore(scenarioCfg[type].name,state.language==='DE')} ${state.language==='DE'?'gestartet':'injected'}`);render();}
function setup(){$$('[data-view-link]').forEach(b=>b.onclick=()=>showView(b.dataset.viewLink));$('#startBtn').onclick=start;$('#pauseBtn').onclick=pause;$('#steadyBtn').onclick=steady;$('#stopBtn').onclick=stopReset;$('#injectBtn').onclick=()=>$('#scenarioDialog').showModal();$('#quickInjectConfirm').onclick=()=>{inject($('#quickScenario').value,$('#quickSeverity').value);$('#scenarioDialog').close();showView('overview')};$('#scenarioRunBtn').onclick=()=>{inject($('#scenarioSelect').value,$('#severitySelect').value);showView('overview')};$('#scenarioClearBtn').onclick=steady;$('#displayMode').onchange=e=>{state.displayMode=e.target.value;renderPfd();toast(`${state.language==='DE'?'PFD-Anzeige':'PFD display'}: ${e.target.options[e.target.selectedIndex].text}`)};$('#roleSelect').onchange=e=>{state.role=e.target.value;showView(e.target.value);toast(state.language==='DE'?(e.target.value==='overview'?'Übersichts-Arbeitsbereich':e.target.value==='operator'?'Operator-Arbeitsbereich':'Engineering-Arbeitsbereich'):(e.target.value==='overview'?'Overview workspace':e.target.value==='operator'?'Operator workspace':'Engineer workspace'))};$('#speedSelect').value=String(state.speed);$('#speedSelect').onchange=e=>{state.speed=Number(e.target.value);localStorage.setItem('pgSpeed',String(state.speed));toast(`${state.language==='DE'?'Demo-Geschwindigkeit':'Demo speed'} ${state.speed}×`)};$('#languageSelect').value=state.language;$('#languageSelect').onchange=e=>{state.language=e.target.value;localStorage.setItem('pgLanguage',state.language);render();toast(state.language==='DE'?'Sprache auf Deutsch umgestellt':'Language switched to English')};$('#selectedTrend').onchange=e=>{state.selectedTrend=e.target.value;renderSelectedTrend();applyLanguage()};$$('[data-hours]').forEach(b=>b.onclick=()=>{state.trendHours=+b.dataset.hours;$$('[data-hours]').forEach(x=>x.classList.toggle('active',x===b));renderSelectedTrend();applyLanguage()});$$('#workspaceTabs button').forEach(b=>b.onclick=()=>{state.workspaceTab=b.dataset.tab;$$('#workspaceTabs button').forEach(x=>x.classList.toggle('active',x===b));$('#workspaceContent').innerHTML=workspaceHtml();applyLanguage()});$('#tagSearch').oninput=e=>{let q=e.target.value.toLowerCase();$$('#tagTableWrap tr').forEach((r,i)=>{if(i===0)return;r.style.display=r.textContent.toLowerCase().includes(q)?'':'none'})};}

seedHistory();setup();render();setInterval(tick,1000);setInterval(updateRealClock,1000);